fn decode_png(path: &str) -> (u32, u32, Vec<u8>) {
    let data = std::fs::read(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    let decoder = png::Decoder::new(Cursor::new(data));
    let mut reader = decoder.read_info().expect("read png info");
    let mut buf = vec![0u8; reader.output_buffer_size().expect("png size")];
    let info = reader.next_frame(&mut buf).expect("png next frame");
    buf.truncate(info.buffer_size());
    let rgb = match info.color_type {
        png::ColorType::Rgb => buf,
        png::ColorType::Rgba => {
            let mut out = Vec::with_capacity((buf.len() / 4) * 3);
            for chunk in buf.chunks_exact(4) {
                out.extend_from_slice(&chunk[0..3]);
            }
            out
        }
        other => panic!("unexpected png color type: {other:?}"),
    };
    (info.width, info.height, rgb)
}

fn encode_default(rgb: &[u8], w: u32, h: u32, q: u32) -> Vec<u8> {
    let cfg = EncoderConfig::ycbcr(q as f32, ChromaSubsampling::Quarter);
    let mut enc = cfg
        .encode_from_bytes(w, h, PixelLayout::Rgb8Srgb)
        .expect("encoder");
    enc.push_packed(rgb, Unstoppable).expect("push");
    enc.finish().expect("finish")
}

fn sha256_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    format!("{:x}", hasher.finalize())
}

#[test]
fn default_build_matches_origin_main_lineart_corpus() {
    let base = std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR");
    let dir = std::path::Path::new(&base).join(LINEART_DIR);
    if !dir.exists() {
        // Corpus is part of the repo under benchmarks/; if a downstream
        // consumer built the crate from a .crate tarball (which strips
        // `benchmarks/`), skip silently. The locked_values test covers
        // encoder determinism via a different path in that environment.
        eprintln!(
            "lineart corpus missing at {:?}; skipping byte-identity test \
             (this is expected when building from a packaged .crate file)",
            dir
        );
        return;
    }

    let mut last_stem: Option<&str> = None;
    let mut cached_img: Option<(u32, u32, Vec<u8>)> = None;

    for &(stem, expected_w, q, expected_hash, expected_len) in PINNED {
        let path = dir.join(format!("{stem}.png"));

        // Cache the decoded PNG across quality levels for the same stem.
        if last_stem != Some(stem) {
            cached_img = Some(decode_png(path.to_str().unwrap()));
            last_stem = Some(stem);
        }
        let (w, h, ref rgb) = *cached_img.as_ref().unwrap();
        assert_eq!(w, expected_w, "{stem} width drift");
        assert_eq!(h, expected_w, "{stem} height drift (corpus is square)");

        let jpeg = encode_default(rgb, w, h, q);
        let hash = sha256_hex(&jpeg);

        assert_eq!(
            jpeg.len(),
            expected_len,
            "{stem}@q{q}: length drift — default build diverged from \
             origin/main. Either encoder behavior changed (and this \
             test needs regenerated hashes alongside locked_values.rs), \
             or the boundary-RD gating leaked into the default path.",
        );
        assert_eq!(
            hash, expected_hash,
            "{stem}@q{q}: SHA-256 drift — default build diverged from \
             origin/main. Either encoder behavior changed (and this \
             test needs regenerated hashes alongside locked_values.rs), \
             or the boundary-RD gating leaked into the default path.",
        );
    }
}
